/* 01 · 设计令牌与基础层 */
:root {
  color-scheme: light;
  --bg: #f6f4ef;
  --surface: #fffaf0;
  --text: #292820;
  --muted: #696356;
  --accent: #80602d;
  --border: #d8cfbd;

  --reader-size: 20px;
  --reader-leading: 1.8;
  --font-serif: "Songti SC", "STSong", "SimSun", serif;
  --font-sans: system-ui, -apple-system, "Segoe UI", "PingFang SC",
    "Microsoft YaHei", sans-serif;
  --font-mono: ui-monospace, "SFMono-Regular", Consolas, "Liberation Mono",
    monospace;
  --reader-font: var(--font-serif);
  --terminal-bg: #0a0e27;
  --terminal-text: #9cc2ff;

  --radius: 12px;
  --figure-radius: 8px;
  --shadow: 0 12px 40px #0003;
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-5: 24px;
  --space-6: 32px;
  --space-7: 48px;
  --space-8: 64px;

  --site-width: 1120px;
  --reader-width: 38em;
  --site-gutter: 40px;
  --grid-gap: 24px;
  --topbar-height: 56px;
  --bottombar-height: 48px;
  --touch-target: 44px;
  --motion-duration: 160ms;
}

html[data-theme] {
  color-scheme: light;
}

html[data-theme="light"] {
  --bg: #ffffff;
  --surface: #f5f7f8;
  --text: #20262c;
  --muted: #58616b;
  --accent: #365f78;
  --border: #d7dde2;
}

html[data-theme="dark"] {
  color-scheme: dark;
  --bg: #171c22;
  --surface: #222a33;
  --text: #e3e8ed;
  --muted: #adb9c6;
  --accent: #e1bd79;
  --border: #46515e;
}

html[data-theme="night"] {
  color-scheme: dark;
  --bg: #191610;
  --surface: #242016;
  --text: #ded0b2;
  --muted: #b2a487;
  --accent: #d2ae70;
  --border: #514634;
}

html[data-font="sans"] {
  --reader-font: var(--font-sans);
}

@media (prefers-color-scheme: dark) {
  html:not([data-theme]) {
    color-scheme: dark;
    --bg: #171c22;
    --surface: #222a33;
    --text: #e3e8ed;
    --muted: #adb9c6;
    --accent: #e1bd79;
    --border: #46515e;
  }
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  min-height: 100%;
  background: var(--bg);
  font-size: 100%;
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
  scroll-padding-block-start: var(--space-5);
}

body {
  min-width: 0;
  min-height: 100vh;
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font-sans);
  font-size: 15px;
  line-height: 1.5;
}

h1,
h2,
h3,
h4,
h5,
h6 {
  margin: 0 0 var(--space-4);
  color: var(--text);
  font-weight: 650;
  line-height: 1.25;
  overflow-wrap: break-word;
}

h1 { font-size: 2.5rem; }
h2 { font-size: 2rem; }
h3 { font-size: 1.5rem; }
h4 { font-size: 1.25rem; }
h5 { font-size: 1.125rem; }
h6 { font-size: 1rem; }

p,
ul,
ol,
dl,
blockquote,
figure {
  margin: 0 0 var(--space-4);
}

ul,
ol {
  padding-inline-start: 1.75em;
}

a {
  color: var(--accent);
  text-decoration-thickness: 1px;
  text-underline-offset: 0.2em;
}

a:hover {
  text-decoration-thickness: 2px;
}

img {
  display: block;
  max-width: 100%;
  height: auto;
  border: 0;
}

hr {
  height: 0;
  margin: var(--space-6) 0;
  border: 0;
  border-block-start: 1px solid var(--border);
}

button,
input,
select,
textarea {
  font: inherit;
}

button,
select,
textarea,
input:not([type="range"]):not([type="checkbox"]):not([type="radio"]) {
  color: inherit;
}

button {
  cursor: pointer;
}

button:disabled,
input:disabled,
select:disabled,
textarea:disabled {
  cursor: not-allowed;
}

code,
kbd,
samp,
pre {
  font-family: var(--font-mono);
}

::selection {
  background: var(--accent);
  color: var(--bg);
}

:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.site-shell,
.site-container {
  width: 100%;
  max-width: var(--site-width);
  margin-inline: auto;
  padding-inline: var(--site-gutter);
}

.site-shell .site-container {
  padding-inline: 0;
}

.site-header {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-4) var(--space-5);
  min-height: var(--topbar-height);
  padding-block: var(--space-4);
  border-block-end: 1px solid var(--border);
}

.site-footer {
  margin-block-start: var(--space-8);
  padding-block: var(--space-5) var(--space-6);
  border-block-start: 1px solid var(--border);
  color: var(--muted);
  font-size: 0.875rem;
  overflow-wrap: anywhere;
}

.skip-link {
  position: fixed;
  z-index: 1000;
  inset-block-start: var(--space-3);
  inset-inline-start: var(--space-3);
  max-width: calc(100% - 24px);
  min-height: var(--touch-target);
  padding: var(--space-3) var(--space-4);
  transform: translateY(calc(-100% - 24px));
  border: 1px solid var(--accent);
  border-radius: var(--radius);
  background: var(--surface);
  color: var(--accent);
  font-weight: 600;
}

.skip-link:focus {
  transform: translateY(0);
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  clip-path: inset(50%);
  border: 0;
  white-space: nowrap;
}

html:not([data-js]) .js-only {
  display: none;
}

.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  min-width: var(--touch-target);
  min-height: var(--touch-target);
  padding: var(--space-3) var(--space-5);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--surface);
  color: var(--text);
  font: inherit;
  font-weight: 600;
  line-height: 1.5;
  text-align: center;
  text-decoration: none;
  cursor: pointer;
  transition: border-color var(--motion-duration) ease;
}

.button:hover {
  border-color: var(--accent);
  text-decoration: none;
}

.button-primary {
  border-color: var(--accent);
  background: var(--accent);
  color: var(--bg);
}

.button-secondary {
  background: transparent;
  color: var(--accent);
}

.button:disabled,
.button[aria-disabled="true"] {
  opacity: 0.55;
  cursor: not-allowed;
}

.text-link {
  color: var(--accent);
  text-decoration-line: underline;
  text-underline-offset: 0.25em;
  overflow-wrap: anywhere;
}

.card {
  min-width: 0;
  padding: var(--space-5);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--surface);
}

.eyebrow {
  margin: 0 0 var(--space-3);
  color: var(--muted);
  font-size: 0.8125rem;
  font-weight: 600;
  letter-spacing: 0.12em;
}

.section-heading {
  margin-block: 0 var(--space-5);
  font-size: 1.5rem;
}

@media (max-width: 767px) {
  :root {
    --site-gutter: 20px;
    --grid-gap: 16px;
  }
  body { font-size: 14px; }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation: none;
    transition: none;
    scroll-behavior: auto;
  }
}
